extension CreatureAppearance {
    /// A source used by the game's renderer for this saved appearance. A client can use it to
    /// choose a representative color; image decoding, sampling and UI contrast are client work.
    public enum ColorSource: Sendable, Hashable {
        /// Packed 0xRRGGBB renderer multiplier, without lighting or live animation.
        case tint(UInt32)
        /// Adult texture identifier for GameAssets.texture(_:); pixels come from the installed game.
        case texture(String)
    }

    /// Code-only renderer facts are generated by the release tool. Unknown species/variants
    /// return nil without changing or discarding the saved appearance. This describes a saved
    /// color, not a live animated frame (such as a jeb_ sheep) or a complete rendered entity.
    public func colorSource(for species: String) -> ColorSource? {
        guard let species = Identifier(species), let variant, let variant = Identifier(variant) else { return nil }
        return GeneratedCreatureColors.sources[species.description]?[variant.description]
    }
}
